'use strict';
(() => {
const panel=document.getElementById('installer');if(!panel)return;
const root=new URL(document.body.dataset.root||'./',location.href),status=document.getElementById('install-status'),select=document.getElementById('install-select'),install=document.getElementById('install-run'),undo=document.getElementById('install-undo');
const EMPTY_SHA256='e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
const OWNER='.skilllantern-owned.json';let project=null,manifest=null,payload=null;
let busy=false;const setBusy=v=>{busy=v;select.disabled=v;install.disabled=v||!project;undo.disabled=v||!project};
const say=t=>{status.textContent=t};
const safePath=p=>typeof p==='string'&&/^motion-design\/(?:[a-zA-Z0-9_-]+\/)*(?:[a-zA-Z0-9_.-]+)$/.test(p)&&!p.split('/').some(v=>v==='.'||v==='..')&&p!=='motion-design/'+OWNER;
const hash=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b))).map(v=>v.toString(16).padStart(2,'0')).join('');
const sameOrigin=async relative=>{const url=new URL(relative,root);if(url.origin!==location.origin||!url.pathname.startsWith(root.pathname))throw Error('Invalid package location.');const r=await fetch(url);if(!r.ok)throw Error('Package unavailable. Use the ZIP instead.');return r};
const dir=async(base,parts,create=false)=>{let h=base;for(const p of parts)h=await h.getDirectoryHandle(p,{create});return h};
const read=async(base,name)=>{try{return await(await base.getFileHandle(name)).getFile()}catch(e){if(e.name==='NotFoundError')return null;throw e}};
const getOwner=async base=>{const f=await read(base,OWNER);if(!f)return null;let x;try{x=JSON.parse(await f.text())}catch{throw Error('Ownership record is corrupt. No files changed. Inspect this skill folder manually or use a new project; automatic undo is unavailable.')} if(x.owner!=='SkillLantern'||x.id!=='motion-design'||x.commit!==manifest.sourceCommit||!Array.isArray(x.files)||new Set(x.files.map(v=>v.path)).size!==x.files.length||x.files.some(v=>!safePath('motion-design/'+v.path)||!/^[a-f0-9]{64}$/.test(v.sha256)||!payload?.some(f=>f.path===v.path&&f.sha256===v.sha256)))throw Error('Ownership record is invalid. No changes made.');return x};
const prepare=async()=>{manifest=await(await sameOrigin('assets/installer-package.json')).json();if(manifest.id!=='motion-design'||!Array.isArray(manifest.files)||manifest.files.length!==18||manifest.files.some(f=>!safePath(f.relativePath)||!(/\.md$|\/LICENSE$/).test(f.relativePath)||!f.url.startsWith('assets/install-package/')||!/^[a-f0-9]{64}$/.test(f.sha256)||!Number.isInteger(f.size)||f.size>32768)||new Set(manifest.files.map(f=>f.relativePath)).size!==18)throw Error('Package manifest is invalid.');payload=[];let total=0;for(const f of manifest.files){const b=await(await sameOrigin(f.url)).arrayBuffer();total+=b.byteLength;if(b.byteLength!==f.size||total>100000||await hash(b)!==f.sha256)throw Error('Package verification failed. No files written.');payload.push({...f,bytes:b,path:f.relativePath.slice('motion-design/'.length)})}document.getElementById('install-file-plan').textContent=payload.map(f=>'.agents/skills/'+f.relativePath).join('\n')};
const start=async()=>{try{await prepare();if(window.top!==window.self||!window.isSecureContext||typeof window.showDirectoryPicker!=='function'){select.disabled=true;say('Use a top-level Chrome or Edge HTTPS tab for folder installation. The ZIP and manual guide work in other browsers.');return}say('18 verified text files. Choose your project folder to preview installation.')}catch(e){say('Package unavailable in this context. Use a top-level HTTPS Chrome or Edge tab, or the ZIP/manual guide below. '+e.message);select.disabled=true}};
select.addEventListener('click',async()=>{if(busy)return;try{project=await window.showDirectoryPicker({mode:'readwrite'});install.disabled=false;undo.disabled=false;say(`Selected “${project.name}”. Only .agents/skills/motion-design will be touched. Review the file plan, then choose Install files.`)}catch(e){project=null;install.disabled=undo.disabled=true;say(e.name==='AbortError'?'Folder selection cancelled. Nothing changed.':'Folder access was not granted. Use the ZIP or try again.')}});
install.addEventListener('click',async()=>{if(busy||!project||!payload)return;setBusy(true);try{let folder;try{folder=await dir(project,['.agents','skills','motion-design'])}catch(e){if(e.name!=='NotFoundError')throw e}if(folder){const owned=await getOwner(folder);if(!owned)throw Error('A Motion Design folder already exists without our ownership record. Nothing overwritten.');if(owned.commit!==manifest.sourceCommit||owned.files.length!==payload.length||owned.files.some(v=>!payload.some(f=>f.path===v.path&&f.sha256===v.sha256)))throw Error('A different owned version exists. Nothing overwritten.');for(const f of payload){const parent=await dir(folder,f.path.split('/').slice(0,-1));const current=await read(parent,f.path.split('/').at(-1));if(!current||await hash(await current.arrayBuffer())!==f.sha256)throw Error('Owned files were changed or removed. Nothing overwritten.')}say('The same verified files are already installed. Agent activation is still pending.');return}folder=await dir(project,['.agents','skills','motion-design'],true);const created=[];let active=null;try{for(const f of payload){const parent=await dir(folder,f.path.split('/').slice(0,-1),true);const name=f.path.split('/').at(-1);if(await read(parent,name))throw Error('A new file appeared in the target folder. Nothing overwritten.');const handle=await parent.getFileHandle(name,{create:true});if((await handle.getFile()).size!==0)throw Error('A nonempty file appeared before writing. It was preserved; inspect the target folder.');active={parent,name,handle,sha256:EMPTY_SHA256};active.allowed=[active.sha256,f.sha256];created.push(active);const stream=await handle.createWritable();await stream.write(f.bytes);await stream.close();active.sha256=await hash(await(await handle.getFile()).arrayBuffer());if(active.sha256!==f.sha256)throw Error('Written-file verification failed.');active=null}
if(await read(folder,OWNER))throw Error('An ownership file appeared. It was preserved.');const owner=await folder.getFileHandle(OWNER,{create:true});if((await owner.getFile()).size!==0)throw Error('A nonempty ownership file appeared before writing. It was preserved.');active={parent:folder,name:OWNER,handle:owner,sha256:EMPTY_SHA256};const ownerText=JSON.stringify({owner:'SkillLantern',id:'motion-design',commit:manifest.sourceCommit,files:payload.map(f=>({path:f.path,sha256:f.sha256}))});active.allowed=[active.sha256,await hash(new TextEncoder().encode(ownerText))];created.push(active);const out=await owner.createWritable();await out.write(ownerText);await out.close();active.sha256=await hash(await(await owner.getFile()).arrayBuffer());active=null;
}catch(e){let kept=0;for(const record of created.reverse()){try{const current=await read(record.parent,record.name);if(!current)continue;if(!record.allowed?.includes(await hash(await current.arrayBuffer()))){kept++;continue}await record.parent.removeEntry(record.name)}catch{kept++}}throw Error('Installation stopped. '+(kept?'Rollback kept '+kept+' changed or inaccessible files; inspect the skill folder manually.':'All files created by this attempt were rolled back; empty directories may remain.')+' '+e.message)}say('18 files installed and hash-verified. Open this project in Codex and check /skills or $motion-design. Agent activation has not been verified.')}catch(e){say(e.message)}finally{setBusy(false)}});
undo.addEventListener('click',async()=>{if(busy||!project)return;setBusy(true);try{const folder=await dir(project,['.agents','skills','motion-design']);const owned=await getOwner(folder);if(!owned)throw Error('No valid ownership record. Nothing removed.');let removed=0,skipped=0;const remaining=[];for(const f of owned.files){try{const parent=await dir(folder,f.path.split('/').slice(0,-1));const current=await read(parent,f.path.split('/').at(-1));if(!current)continue;if(await hash(await current.arrayBuffer())!==f.sha256){skipped++;remaining.push(f);continue}await parent.removeEntry(f.path.split('/').at(-1));removed++}catch(e){if(e.name!=='NotFoundError'){skipped++;remaining.push(f)}}}if(remaining.length){const h=await folder.getFileHandle(OWNER);const w=await h.createWritable();await w.write(JSON.stringify({...owned,files:remaining}));await w.close()}else await folder.removeEntry(OWNER);say(`Removed ${removed} owned, unmodified files. Kept ${skipped} changed files. Unowned files and project folders were left in place.`)}catch(e){say(e.name==='NotFoundError'?'No installed folder found. Nothing removed.':e.message)}finally{setBusy(false)}});
start();
})();
